import{_ as e,o as i,c as s,a2 as l}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"编译、部署与调试","description":"","frontmatter":{"title":"编译、部署与调试","order":5},"headers":[],"relativePath":"zh/learn/mod/build-debug.md","filePath":"zh/learn/mod/build-debug.md","lastUpdated":1786943111000}'),o={name:"zh/learn/mod/build-debug.md"};function n(d,a,t,r,h,p){return i(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="编译、部署与调试" tabindex="-1">编译、部署与调试 <a class="header-anchor" href="#编译、部署与调试" aria-label="Permalink to &quot;编译、部署与调试&quot;">​</a></h1><p>写完代码，怎么把它跑进游戏里？</p><h2 id="编译" tabindex="-1">编译 <a class="header-anchor" href="#编译" aria-label="Permalink to &quot;编译&quot;">​</a></h2><p>用 Visual Studio / Rider 或命令行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>模板项目引用的是<strong>游戏目录里的 DLL</strong>，所以编译前请确保：</p><ul><li>游戏已经通过 UMM 安装（注入）</li><li><code>.csproj</code> 中引用的程序集路径存在（通常是 <code>$(ADOFAI_PATH)</code> 或相对路径）</li></ul><h2 id="部署-把产物放进-mods" tabindex="-1">部署：把产物放进 Mods <a class="header-anchor" href="#部署-把产物放进-mods" aria-label="Permalink to &quot;部署：把产物放进 Mods&quot;">​</a></h2><p>模板通常配置了「编译后自动复制」：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MyFirstMod.dll  →  ADOFAI/Mods/MyFirstMod/</span></span>
<span class="line"><span>Info.json       →  ADOFAI/Mods/MyFirstMod/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>如果模板没有自动部署，手动复制即可。<strong>发布时也同样要把这两个文件放到一起。</strong></p><h2 id="在游戏中验证" tabindex="-1">在游戏中验证 <a class="header-anchor" href="#在游戏中验证" aria-label="Permalink to &quot;在游戏中验证&quot;">​</a></h2><ol><li>启动游戏，打开 UMM 界面（默认 <code>Ctrl+F10</code>）</li><li>在 Mod 列表中找到 MyFirstMod，勾选启用</li><li>观察日志是否输出 <code>Mod loaded</code></li><li>若列表里没有你的 Mod，检查： <ul><li><code>Info.json</code> 的 <code>AssemblyName</code> 是否等于实际 DLL 文件名</li><li><code>EntryMethod</code> 是否为 <code>命名空间.类.Load</code></li><li>编译产物是否真的复制到了 <code>Mods/</code> 下</li></ul></li></ol><h2 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to &quot;调试技巧&quot;">​</a></h2><h3 id="_1-用日志定位问题" tabindex="-1">1. 用日志定位问题 <a class="header-anchor" href="#_1-用日志定位问题" aria-label="Permalink to &quot;1. 用日志定位问题&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">modEntry.Logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$&quot;当前值: {</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 输出到 UMM 界面</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-修改后热重载" tabindex="-1">2. 修改后热重载 <a class="header-anchor" href="#_2-修改后热重载" aria-label="Permalink to &quot;2. 修改后热重载&quot;">​</a></h3><p>UMM 支持在游戏内<strong>禁用再启用</strong> Mod：在 UMM 界面取消勾选再重新勾选。这样不用重启游戏就能应用新代码（前提是你重新编译并覆盖了 DLL）。</p><h3 id="_3-崩溃时看-player-log" tabindex="-1">3. 崩溃时看 Player.log <a class="header-anchor" href="#_3-崩溃时看-player-log" aria-label="Permalink to &quot;3. 崩溃时看 Player.log&quot;">​</a></h3><p>Mod 抛出的异常会写在游戏日志里（见<a href="./umm">认识 UMM</a>的日志位置）。看到 <code>NullReferenceException</code> 时，先确认：</p><ul><li>是否在 <code>OnToggle</code> 之前就访问了 <code>Settings</code></li><li>Harmony 补丁的签名是否与目标方法一致</li></ul><h3 id="_4-附加调试器-可选" tabindex="-1">4. 附加调试器（可选） <a class="header-anchor" href="#_4-附加调试器-可选" aria-label="Permalink to &quot;4. 附加调试器（可选）&quot;">​</a></h3><p>在 IDE 中「附加到进程」选择 <code>A Dance of Fire and Ice.exe</code>，可以直接在 C# 代码里打断点。注意需要以<strong>调试配置</strong>编译，且游戏要先启动。</p><h2 id="你学到了什么" tabindex="-1">你学到了什么 <a class="header-anchor" href="#你学到了什么" aria-label="Permalink to &quot;你学到了什么&quot;">​</a></h2><ul><li>编译与部署 Mod 到游戏目录</li><li>在游戏中启用、验证、热重载 Mod</li><li>用日志与 <code>Player.log</code> 排查问题</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>学会用 Harmony 修改游戏行为 → <a href="./harmony">Harmony 入门</a></p>`,27)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
